}

Method.Source:
    /// <summary>
    /// Inserts the request for quotation line.
    /// </summary>
    protected void insertRequestForQuotationLine()
    {
        CompanyInfo companyInfo = CompanyInfo::find();      
       
        tmpPurchRFQSend.Phone = companyInfo.phone();
        tmpPurchRFQSend.KPMGCompanyEmail = companyInfo.email();
        tmpPurchRFQSend.Telefax = companyInfo.teleFax();

        next insertRequestForQuotationLine();
    }
